<?php require_once __DIR__.'/config/config.php';require_login();$uid=current_user_id();$s=$conn->prepare("SELECT n.*,u.username,u.display_name,p.id AS valid_post FROM notifications n JOIN users u ON u.id=n.actor_id LEFT JOIN posts p ON p.id=n.post_id WHERE n.user_id=? ORDER BY n.created_at DESC LIMIT 100");$s->bind_param('i',$uid);$s->execute();$items=$s->get_result();$s=$conn->prepare('UPDATE notifications SET is_read=1 WHERE user_id=?');$s->bind_param('i',$uid);$s->execute();$page_title='Notifications';require __DIR__.'/includes/header.php';?><div class="page-heading"><p class="eyebrow">STAY IN THE LOOP</p><h1>Notifications ♡</h1></div><?php if(!$items->num_rows):?><div class="empty-state">You are all caught up!</div><?php endif;?><?php while($n=$items->fetch_assoc()):$label=['comment'=>'commented on your post','reaction'=>'reacted to your post','follow'=>'started following you'][$n['type']];?><a class="card notification-item<?=$n['is_read']?'':' is-new'?>" href="<?= $n['type']==='follow'?BASE_URL.'/profile.php?u='.rawurlencode($n['username']):($n['valid_post']?BASE_URL.'/post.php?id='.(int)$n['post_id']:BASE_URL.'/index.php')?>"><strong><?=e($n['display_name'])?></strong> <?=e($label)?> <small><?=e($n['created_at'])?></small></a><?php endwhile;?><?php require __DIR__.'/includes/footer.php';?>